{
  "technical_and_design_decisions": [
    "Adopt Spring Boot 1.2.0 dependency management BOM to centralize version upgrades for all listed libraries.",
    "Implement a pluggable CompressionAlgorithm interface supporting GZIP and ZIP (DEFLATE) for generic message compression (U7) and reuse it in Rabbit modules (U8).",
    "For Mail sink TLS, expose a javaMailProperties map in module configuration and pass it to Spring Integration Mail adapters, allowing IMAP/SMTP SSL/TLS.",
    "For HDFS dataset sink, use Avro's CodecFactory to allow configuration of codec (e.g., null/snappy/deflate) instead of hard-coded Snappy.",
    "For deployment manifest, use SnakeYAML (provided by Spring Boot) to parse an optional external YML file and merge properties with stream definition at deployment time.",
    "For partitionResultsTimeout, add the attribute to the job metadata generation so it is available for all jobs importing the partitioning strategy, and update wiki.",
    "Benchmark for U1 will be delivered as a sample Spring Batch job configuration and a timing/logging harness rather than a full automated CI benchmark suite."
  ],
  "assumptions": [
    "The existing codebase is Spring XD (or similar) currently aligned with Spring Boot 1.1.x; the upgrade primarily involves version bumps and fixing breaking API changes.",
    "The jdbchdfs batch job already exists; the benchmark task only requires configuration, measurement, and reporting, not new job logic.",
    "The developer has expert-level knowledge of Spring Framework, Spring XD, and Java, and performs all coding, testing, and documentation personally.",
    "A working continuous integration environment is available to execute the existing test suite after the dependency upgrade.",
    "All new module options will be exposed through the existing configuration metadata mechanism without requiring new UI work.",
    "Compression is applied at the message payload level; for Rabbit, compression is added as a message converter option rather than broker-level compression.",
    "Effort estimates exclude calendar delays, meetings, and external code review, focusing solely on development work-hours."
  ],
  "activities": [
    {
      "activity_id": "WBS1.1",
      "activity_name": "Update POMs and dependency versions",
      "activity_description": "Modify parent POM and dependency management to upgrade to Spring Boot 1.2.0.RELEASE and aligned library versions (Spring, Spring Batch, Hibernate, etc.) as listed in U5.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "WBS1.2",
      "activity_name": "Resolve compilation and API changes",
      "activity_description": "Fix source code for breaking changes introduced by upgraded Spring, Spring Batch, Hibernate, and other libraries to achieve a clean compile.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "WBS1.3",
      "activity_name": "Run and fix test suite and integration tests",
      "activity_description": "Execute unit, integration, and system tests after upgrade; diagnose and fix failures caused by dependency changes.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "WBS1.4",
      "activity_name": "Verify upgrade and update documentation",
      "activity_description": "Perform manual smoke tests of key modules, verify compatibility, and update README/build docs for new dependency versions.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "WBS2.1",
      "activity_name": "Create benchmark harness for Sqoop vs jdbchdfs",
      "activity_description": "Develop a benchmark configuration and timing/logging harness (sample job) that allows a QA to compare Sqoop and jdbchdfs batch job performance (U1).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "WBS2.2",
      "activity_name": "Execute benchmarks and document performance stats",
      "activity_description": "Run the benchmark harness, collect performance statistics, and produce a comparison document for QA (U1).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "WBS3.1",
      "activity_name": "Implement Avro codec configuration in hdfs-dataset sink",
      "activity_description": "Modify hdfs-dataset sink to allow disabling Snappy and selecting an alternative Avro codec via configuration (U2).",
      "most_likely_effort": 10
    },
    {
      "activity_id": "WBS3.2",
      "activity_name": "Unit and integration tests for codec options",
      "activity_description": "Add automated tests verifying that Avro files are written with the configured codec (including none/snappy/other) (U2).",
      "most_likely_effort": 6
    },
    {
      "activity_id": "WBS3.3",
      "activity_name": "Document codec configuration",
      "activity_description": "Update module reference documentation describing the new codec option for hdfs-dataset sink (U2).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "WBS4.1",
      "activity_name": "Add TLS/java-mail-properties support to Mail sink",
      "activity_description": "Extend Mail sink configuration to accept a java-mail-properties bean (e.g., TLS/SSL properties) and pass them to IMAP/SMTP adapters (U3).",
      "most_likely_effort": 12
    },
    {
      "activity_id": "WBS4.2",
      "activity_name": "Tests for secured IMAP/SMTP",
      "activity_description": "Add tests connecting to secured mail servers using TLS with provided java-mail properties (U3).",
      "most_likely_effort": 6
    },
    {
      "activity_id": "WBS4.3",
      "activity_name": "Document Mail sink TLS configuration",
      "activity_description": "Provide XML examples and property descriptions for TLS-enabled Mail sink in docs (U3).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "WBS5.1",
      "activity_name": "Expose partitionResultsTimeout metadata attribute",
      "activity_description": "Ensure partitionResultsTimeout is exposed as a metadata attribute for all jobs inheriting singlestep-partitioning strategy and update the wiki accordingly (U4).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "WBS6.1",
      "activity_name": "Implement separate YML deployment manifest parsing",
      "activity_description": "Develop support for an optional external YML file listing deployment manifest properties, parsed and merged with stream definitions at deploy time (U6).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "WBS6.2",
      "activity_name": "Tests for YML manifest",
      "activity_description": "Add unit and integration tests for loading and merging YML deployment manifests (U6).",
      "most_likely_effort": 6
    },
    {
      "activity_id": "WBS6.3",
      "activity_name": "Document YML manifest usage",
      "activity_description": "Update documentation describing the new separate YML deployment manifest file (U6).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "WBS7.1",
      "activity_name": "Design and implement generic message compression utility",
      "activity_description": "Create a pluggable compression component supporting gzip and zip (de)compression for messages, configurable via module options (U7).",
      "most_likely_effort": 20
    },
    {
      "activity_id": "WBS7.2",
      "activity_name": "Tests for compression/decompression",
      "activity_description": "Add tests verifying round-trip compression/decompression and performance options (U7).",
      "most_likely_effort": 6
    },
    {
      "activity_id": "WBS7.3",
      "activity_name": "Document compression option",
      "activity_description": "Document the generic message compression feature and available codecs (U7).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "WBS8.1",
      "activity_name": "Integrate compression into Rabbit source and sink",
      "activity_description": "Extend Rabbit source and sink modules to optionally use the generic compression utility for message payloads (U8).",
      "most_likely_effort": 12
    },
    {
      "activity_id": "WBS8.2",
      "activity_name": "Tests for Rabbit compression",
      "activity_description": "Add tests for compressed message exchange between Rabbit source and sink (U8).",
      "most_likely_effort": 6
    },
    {
      "activity_id": "WBS8.3",
      "activity_name": "Document Rabbit compression",
      "activity_description": "Update Rabbit module docs with compression configuration examples (U8).",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 230
  }
}

